const fs=require('fs'),path=require('path'),{chromium}=require('playwright');const a=process.argv.slice(2),arg=(n,f='')=>{const i=a.indexOf(n);return i>=0&&a[i+1]?a[i+1]:f};const base=arg('--url','http://localhost/greenportal').replace(/\/$/,''),empresa=arg('--empresa','Modelo'),usuario=arg('--usuario','admin'),senha=arg('--senha', process.env.GREEN_TEST_PASSWORD || ''),cdp=arg('--cdp',''),out=path.resolve(arg('--saida','tests/resultado-ajuda-reload-requisitos-legais-20260924.json'));const result={startedAt:new Date().toISOString(),checks:[],status:'REPROVADO'};const check=(n,o,d='')=>{result.checks.push({name:n,ok:!!o,details:d});console.log(`${o?'PASS':'FAIL'} - ${n}${d?`: ${d}`:''}`);if(!o)throw new Error(n)};async function main(){let b;try{b=cdp?await chromium.connectOverCDP(cdp):await chromium.launch({headless:true});const c=cdp?(b.contexts()[0]||await b.newContext()):await b.newContext();const p=cdp?(c.pages()[0]||await c.newPage()):await c.newPage();p.setDefaultTimeout(20000);await p.goto(base+'/index.php',{waitUntil:'domcontentloaded'});await p.locator('#empresa').selectOption({label:empresa}).catch(()=>p.locator('#empresa').selectOption({value:empresa}));await p.locator('#userid').fill(usuario);await p.locator('#senha').fill(senha);await p.locator('form.login-form button[type="submit"]').click();await p.waitForURL(/\/principal\/main\.php/);await p.locator('[data-sidebar-toggle]').click().catch(()=>{});await p.locator('#menuSearch').fill('Requisitos legais');await p.locator('button[data-open-tab][data-tab-url*="modulolegal_requisitoslegais.php"]').click();const f=p.frameLocator('iframe[src*="modulolegal_requisitoslegais.php"]');await f.locator('#requisitosLegaisBatchGrid tbody tr').first().waitFor({state:'visible'});const row=f.locator('#requisitosLegaisBatchGrid tbody tr').first();await row.click();const help=f.locator('[data-open-transacao-ajuda]');check('Botão Ajuda presente',await help.count()===1);await help.click();const hm=p.locator('[data-popup-transacao-independent].show').last();await hm.waitFor({state:'visible'});const hs=await hm.locator('iframe').getAttribute('src');check('Ajuda abriu com transação correta',hs.includes('setup_ajuda.php?transacao=modulolegal_requisitoslegais'),hs);await hm.locator('.btn-close').click();const mainSrc=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').getAttribute('src'),before=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').count();await f.locator('[data-reload-grid]').click();await f.locator('#requisitosLegaisBatchGrid tbody tr').first().waitFor({state:'visible'});await p.waitForTimeout(500);const after=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').count(),current=await p.locator('iframe[src*="modulolegal_requisitoslegais.php"]').getAttribute('src');check('Recarregar manteve o contexto',before===after&&mainSrc===current,`iframes ${before}->${after}`);check('Recarregar manteve a grade',await f.locator('#requisitosLegaisBatchGrid tbody tr').count()>0);result.status='APROVADO'}catch(e){result.error=e.message;throw e}finally{result.finishedAt=new Date().toISOString();fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify(result,null,2));if(b&&!cdp)await b.close()}}main().catch(e=>{console.error(`ERRO FATAL: ${e.stack||e.message}`);process.exit(1)});
